pub fn signal_by_name(name: &str) -> Option<&'static SignalSpec> {
    SIGNAL_SPECS.iter().find(|spec| spec.name.eq_ignore_ascii_case(name))
}

pub fn signal_by_code(code: u16) -> Option<&'static SignalSpec> {
    SIGNAL_SPECS.iter().find(|spec| spec.code == code)
}

pub fn fault_by_code(code: u16) -> Option<&'static FaultCode> {
    FAULT_CODES.iter().find(|fault| fault.code == code)
}

pub fn route_profile_by_name(name: &str) -> Option<&'static RouteProfile> {
    ROUTE_PROFILES.iter().find(|profile| profile.name.eq_ignore_ascii_case(name))
}

pub fn profile_for_protocol(name: &str) -> Option<&'static ProtocolProfile> {
    PROTOCOL_PROFILES.iter().find(|profile| profile.name.eq_ignore_ascii_case(name))
}

pub fn class_weight(class: SignalClass) -> u32 {
    match class {
        SignalClass::Powertrain => 37,
        SignalClass::Energy => 41,
        SignalClass::Brake => 53,
        SignalClass::Cargo => 29,
        SignalClass::Navigation => 31,
        SignalClass::Chassis => 23,
        SignalClass::Safety => 59,
        SignalClass::Climate => 19,
        SignalClass::Auxiliary => 17,
        SignalClass::Diagnostic => 13,
    }
}

pub fn catalog_digest() -> u32 {
    let mut acc = 0x4654_4c31u32;
    for spec in SIGNAL_SPECS {
        acc = acc.rotate_left(3) ^ spec.code as u32 ^ class_weight(spec.class);
        acc = acc.wrapping_add((spec.max as u32).wrapping_sub(spec.min as u32));
    }
    for fault in FAULT_CODES {
        acc = acc.rotate_left(5) ^ fault.code as u32;
    }
    acc
}
